public class DataFrameJoin {
    public static void main(String[] args) {
        SparkSession spark = SparkSession.builder().appName("DataFrameJoin").getOrCreate();

        // Create sample DataFrames
        Dataset<Row> df1 = createDataFrame();
        Dataset<Row> df2 = createDataFrame();

        System.out.println("Data Frame 1:");
