        joinedDf.show();
    }

    public static Dataset<Row> createDataFrame() {
        SparkSession spark = SparkSession.builder().appName("createDataFrame").getOrCreate();

        // Sample Data Frame 1
        String[] columns = {"id", "name"};
        String[][] data = new String[][]{{"1", "John"}, {"2", "Jane"}};

        Dataset<Row> df1 = spark.createDataFrame(data, columns);
        return df1;
    }

    public static Dataset<Row> joinDataframes(Dataset<Row> df1, Dataset<Row> df2) {
        String[] columns = new String[4]; // adjust the number of columns as needed
        String[][] data = new String[df1.size()][columns.length];
        for (int i = 0; i < df1.size(); i++) {
            for (String key : df1.columns()) {
                if (i == 0) { // add column 'id' to the first DataFrame
                    data[i][0] = df1.columns().get(0);
                } else {
                    data[i][columns.length - 1] = df2.columns().get(columns.length - 1);
                }
            }
        }

        Dataset<Row> joinedDf = spark.createDataFrame(data, columns);

        return joinedDf;
    }

    public static void setColumn(Dataset<Row> table, String columnName) {
        SparkSession spark = SparkSession.builder().appName("setColumn").getOrCreate();

        Dataset<Row> table = joinDataframes(table, createDataFrame());
        table = table.withColumn(columnName, table.select(columnName).alias(columnName));
    }

    public static void addColumn(Dataset<Row> table, String columnName) {
        SparkSession spark = SparkSession.builder().appName("addColumn").getOrCreate();

        Dataset<Row> table = joinDataframes(table, createDataFrame());
        table = table.withColumn(columnName, table.select(columnName).alias(columnName));

